int main() {
  std::vector<int> v{1, 2, 2, 3};
  for (auto it = v.begin();
       it != v.end(); ++it) {
    if (*it == 2)
      it = v.erase(it);
  }
  for (int x : v) std::cout << x << ' ';
}

for (auto it = v.begin(); it != v.end();) {
  if (*it == 2) it = v.erase(it);
  else ++it;
}

// C++20: one call, O(n)
std::erase_if(v, [](int x) { return x == 2; });

int main() {
  std::vector<int> v{100, 200, 300, 400};
  v.reserve(10);
  auto it = v.begin() + 2;   // 300
  v.insert(v.begin(), 50);
  std::cout << *it << '\n';
}

std::vector<int> v{100, 200, 300, 400};
v.reserve(10);
v.insert(v.begin(), 50);
auto it = v.begin() + 3;   // 300
std::cout << *it << '\n';

int main() {
  std::vector<int> v{10, 20, 30, 40, 50};
  for (auto it = v.begin(); it != v.end();
       it += 2)
    std::cout << *it << ' ';
}

for (std::size_t i = 0; i < v.size();
     i += 2)
  std::cout << v[i] << ' ';   // 10 30 50

